// くくダッシュ Service Worker (自動生成: tools/build_gated_web.py)
// キャッシュ名に版数が入っているので、更新時は古いキャッシュが破棄される
var CACHE = "kuku-dash-20261110-69";
var ASSETS = ["./", "./index.html", "./manifest.webmanifest", "./icon.svg"];
self.addEventListener("install", function(e){
  e.waitUntil(caches.open(CACHE).then(function(c){ return c.addAll(ASSETS); })
    .then(function(){ return self.skipWaiting(); }));
});
self.addEventListener("activate", function(e){
  e.waitUntil(caches.keys().then(function(keys){
    return Promise.all(keys.map(function(k){
      if (k !== CACHE) return caches.delete(k);
    }));
  }).then(function(){ return self.clients.claim(); }));
});
var ICON_B64 = {"icon-512.png": "", "icon-192.png": "", "apple-touch-icon.png": ""};
function iconResponse(b64){
  var bin = atob(b64);
  var bytes = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { "Content-Type": "image/png" } });
}
self.addEventListener("fetch", function(e){
  var req = e.request;
  if (req.method !== "GET") return;
  // アイコンPNGは push の都合でサーバに置けないので、SW が合成して返す
  var path = new URL(req.url).pathname;
  for (var name in ICON_B64) {
    if (path.slice(-name.length) === name) {
      e.respondWith(iconResponse(ICON_B64[name]));
      return;
    }
  }
  // 世代交代の競合で旧キャッシュが残ることがあるので、現行SWが
  // リクエストを捌くたびに自分以外のキャッシュを掃除する
  caches.keys().then(function(keys){
    keys.forEach(function(k){ if (k !== CACHE) caches.delete(k); });
  });
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === "navigate") {
    e.respondWith(fetch(req).then(function(res){
      var copy = res.clone();
      caches.open(CACHE).then(function(c){ c.put("./index.html", copy); });
      return res;
    }).catch(function(){
      return caches.match("./index.html", { ignoreSearch: true });
    }));
    return;
  }
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(function(hit){
    if (hit) return hit;
    return fetch(req).then(function(res){
      var copy = res.clone();
      caches.open(CACHE).then(function(c){ c.put(req, copy); });
      return res;
    });
  }));
});
